#include <iostream>
using namespace std;

long long N, K;
const long long MOD = 1000000007LL;
long long Power[65], Res[35][35];
long long S[65][35][35][35], A[65][35][35][35], P[65][35][35][35], Aux[35][35];
pair<long long, long long> X[105];

void copy2(long long dest[][35], long long src[][35], long long size) {
    for (long long i = 0; i < size; ++i) {
        for (long long j = 0; j < size; ++j) {
            dest[i][j] = src[i][j];
        }
    }
}

inline void addMod(long long& a, long long b) {
    a = (a + b) % MOD;
}

void matrixMultiply(long long mat1[][35], long long mat2[][35], long long result[][35], long long rows1, long long cols1, long long cols2) {
    for (long long r = 0; r < rows1; ++r) {
        for (long long c = 0; c < cols2; ++c) {
            result[r][c] = 0;
            for (long long k = 0; k < cols1; ++k) {
                addMod(result[r][c], (mat1[r][k] * mat2[k][c]) % MOD);
            }
        }
    }
}

void precomputeA() {
    for (long long x = 0; x < K; ++x) {
        for (long long i = 0; i < K + 1; ++i) {
            A[0][x][i][i] = 1;
        }
        for (long long j = 0; j < K + 1; ++j) {
            A[0][x][j][x] = 1;
        }
    }

    copy2(P[0][0], A[0][0], K + 1);
    copy2(S[0][K - 1], A[0][K - 1], K + 1);

    for (long long x = 1; x < K; ++x) {
        matrixMultiply(P[0][x - 1], A[0][x], P[0][x], K + 1, K + 1, K + 1);
    }

    for (long long x = K - 2; x >= 0; --x) {
        matrixMultiply(A[0][x], S[0][x + 1], S[0][x], K + 1, K + 1, K + 1);
    }

    long long multiplier = 1;
    int level = 0;
    while (multiplier <= N / K) {
        for (long long x = 0; x < K; ++x) {
            if (x > 0) {
                copy2(A[level][x], S[level - 1][x], K + 1);
                matrixMultiply(A[level][x], P[level - 1][x - 1], Aux, K + 1, K + 1, K + 1);
                copy2(A[level][x], Aux, K + 1);
            } else {
                copy2(A[level][x], S[level - 1][x], K + 1);
            }
        }
        copy2(P[level][0], A[level][0], K + 1);
        copy2(S[level][K - 1], A[level][K - 1], K + 1);

        for (long long x = 1; x < K; ++x) {
            matrixMultiply(P[level][x - 1], A[level][x], P[level][x], K + 1, K + 1, K + 1);
        }

        for (long long x = K - 2; x >= 0; --x) {
            matrixMultiply(A[level][x], S[level][x + 1], S[level][x], K + 1, K + 1, K + 1);
        }

        if (multiplier > N / K / K) break;
        multiplier *= K;
        ++level;
    }
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(0);
    cin >> N >> K;

    Power[0] = 1;
    int powerIndex = 1;
    while (Power[powerIndex - 1] <= N / K) {
        Power[powerIndex] = Power[powerIndex - 1] * K;
        ++powerIndex;
    }

    int maxPowerIndex = powerIndex - 1;
    precomputeA();

    long long remaining = N;
    int currentLevel = 0;
    int digitIndex = 0;
    Res[0][K] = 1;

    for (int p = maxPowerIndex; p >= 0; --p) {
        while (Power[p] <= remaining) {
            matrixMultiply(Res, A[p][digitIndex], Aux, K + 1, K + 1, K + 1);
            copy2(Res, Aux, K + 1);
            digitIndex = (digitIndex + 1) % K;
            remaining -= Power[p];
        }
    }

    long long answer = 0;
    for (int i = 0; i <= K; ++i) {
        addMod(answer, Res[0][i]);
    }
    cout << answer << '\n';
    return 0;
}
